5	namespace Tests\Feature\Events;
6	
7	use App\Enums\PlanTier;
8	use App\Enums\UserRole;
9	use App\Models\User;
10	use App\Modules\Events\Enums\EventState;
11	use App\Modules\Events\Models\Event;
12	use App\Modules\Events\Models\Registration;
13	use App\Modules\Events\Support\EventActionAvailability;
14	use Illuminate\Support\Facades\Cache;
15	use Illuminate\Support\Facades\Hash;
16	use Illuminate\Support\Facades\Route;
17	use PHPUnit\Framework\Attributes\Group;
18	use PHPUnit\Framework\Attributes\Test;
19	use Tests\Feature\Billing\Support\BillingTestFixtures;
20	use Tests\Feature\FeatureTestCase;
21	
22	/**
23	 * Capsule T1 ATDD — Duplicate an event.
24	 *
25	 * Critical path only:
26	 *   - AC1 named POST route on the Events module
27	 *   - AC2/AC3 shared action model exposes `duplicate` gated on the create capability
28	 *   - AC4 endpoint refuses independently of what the UI rendered, with no row written
29	 *   - AC5/AC6 a successful duplicate is a fresh DRAFT copy in the acting team,
30	 *     carrying no lifecycle, cancellation or registration state from the source
31	 */
32	#[Group('events')]
33	class EventDuplicateActionTest extends FeatureTestCase
34	{
35	    use BillingTestFixtures;
36	
37	    protected function setUp(): void
38	    {
39	        parent::setUp();
40	        Cache::flush();
41	    }
42	
43	    // =========================================================================
44	    // AC1 — route contract
45	    // =========================================================================
46	
47	    #[Test]
48	    public function duplicate_route_is_registered_by_name_on_the_events_module(): void
49	    {
50	        $route = Route::getRoutes()->getByName('events.duplicate');
51	
52	        $this->assertNotNull($route, 'Named route [events.duplicate] is not registered.');
53	        $this->assertSame('events/{event:uuid}/duplicate', $route->uri());
54	        $this->assertContains('POST', $route->methods());
55	        $this->assertStringStartsWith(
56	            'App\Modules\Events\\',
57	            $route->getActionName(),
58	            'events.duplicate must be handled by the Events module.',
59	        );
60	    }
61	
62	    // =========================================================================
63	    // AC2 + AC3 — shared action model
64	    // =========================================================================
65	
66	    #[Test]
67	    public function action_model_exposes_duplicate_for_an_actor_with_the_create_capability(): void
68	    {
69	        [$admin] = $this->adminWithPlan(PlanTier::GROWTH);
70	        $event = $this->eventFor($admin, EventState::DRAFT);
71	
72	        $availability = app(EventActionAvailability::class)->for($admin->fresh(), $event);
73	
74	        $this->assertArrayHasKey('duplicate', $availability);
75	        $this->assertSame(
76	            array_keys($availability['edit']),
77	            array_keys($availability['duplicate']),
78	            'duplicate entry must share the shape of the existing action entries.',
79	        );
80	        $this->assertTrue($availability['duplicate']['visible']);
81	        $this->assertTrue($availability['duplicate']['enabled']);
82	    }
83	
84	    #[Test]
85	    public function action_model_hides_duplicate_from_an_actor_without_the_create_capability(): void
86	    {
87	        // billing-admin holds no events.* team capability.
88	        [$admin, $team] = $this->adminWithPlan(PlanTier::GROWTH);
89	        $event = $this->eventFor($admin, EventState::DRAFT);
90	
91	        $billingAdmin = User::factory()->create(['email_verified_at' => now()]);
92	        $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
93	        $billingAdmin->forceFill(['current_team_id' => $team->id])->save();
94	
95	        $availability = app(EventActionAvailability::class)->for($billingAdmin->fresh(), $event);
96	
97	        $this->assertArrayHasKey('duplicate', $availability);
98	        $this->assertFalse($availability['duplicate']['visible']);
99	        $this->assertFalse($availability['duplicate']['enabled']);
100	    }
101	
102	    // =========================================================================
103	    // AC5 + AC6 — successful duplicate
104	    // =========================================================================
105	
106	    #[Test]
107	    public function duplicating_an_event_creates_one_fresh_draft_copy_in_the_acting_team(): void
108	    {
109	        [$admin] = $this->adminWithPlan(PlanTier::GROWTH);
110	
111	        $source = $this->eventFor($admin, EventState::PUBLISHED);
112	        $source->forceFill([
113	            'cancelled_at' => now(),
114	            'cancelled_by' => $admin->id,
115	            'cancel_reason' => 'Speaker dropped out',
116	        ])->save();
117	        $this->registrationFor($source);
118	
119	        $response = $this->actingAs($admin)
120	            ->from(route('events.show', $source))
121	            ->post('/events/'.$source->uuid.'/duplicate');
122	
123	        $response->assertSessionHasNoErrors();
124	        $this->assertContains(
125	            $response->status(),
126	            [200, 201, 302],
127	            'Duplicate should be accepted; got HTTP '.$response->status().'.',
128	        );
129	
130	        $this->assertSame(2, Event::withoutGlobalScopes()->count(), 'Exactly one new event should exist.');
131	
132	        $copy = Event::withoutGlobalScopes()
133	            ->whereKeyNot($source->getKey())
134	            ->sole();
135	
136	        $this->assertNotSame($source->uuid, $copy->uuid);
137	        $this->assertSame(EventState::DRAFT, $copy->state);
138	        $this->assertSame($admin->fresh()->currentTeam->id, $copy->team_id);
139	
140	        // AC6 — no lifecycle / cancellation / registration carry-over.
141	        $this->assertNull($copy->cancelled_at);
142	        $this->assertNull($copy->cancelled_by);
143	        $this->assertNull($copy->cancel_reason);
144	        $this->assertSame(0, $copy->registrations()->withoutGlobalScopes()->count());
145	        $this->assertSame(1, Registration::withoutGlobalScopes()->count());
146	    }
147	
148	    // =========================================================================
149	    // AC4 — endpoint stands on its own authorization
150	    // =========================================================================
151	
152	    #[Test]
153	    public function endpoint_refuses_an_actor_without_the_create_capability_and_writes_no_event(): void
154	    {
155	        [$admin, $team] = $this->adminWithPlan(PlanTier::GROWTH);
156	        $source = $this->eventFor($admin, EventState::DRAFT);
157	
158	        $billingAdmin = User::factory()->create(['email_verified_at' => now()]);
159	        $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
160	        $billingAdmin->forceFill(['current_team_id' => $team->id])->save();
161	
162	        $response = $this->actingAs($billingAdmin->fresh())
163	            ->postJson('/events/'.$source->uuid.'/duplicate');
164	
165	        $response->assertStatus(403);
166	        $this->assertSame(1, Event::withoutGlobalScopes()->count());
167	    }
168	
169	    #[Test]
170	    public function endpoint_refuses_an_actor_who_cannot_view_the_source_event_and_writes_no_event(): void
171	    {
172	        [$owner] = $this->adminWithPlan(PlanTier::GROWTH);
173	        $source = $this->eventFor($owner, EventState::DRAFT);
174	
175	        // Admin of an unrelated workspace: holds events.create.team there,
176	        // but has no visibility of this source event.
177	        [$outsider] = $this->adminWithPlan(PlanTier::GROWTH);
178	
179	        $response = $this->actingAs($outsider->fresh())
180	            ->postJson('/events/'.$source->uuid.'/duplicate');
181	
182	        $this->assertContains(
183	            $response->status(),
184	            [403, 404],
185	            'Cross-workspace duplicate must be refused; got HTTP '.$response->status().'.',
186	        );
187	        $this->assertSame(1, Event::withoutGlobalScopes()->count());
188	    }
189	
190	    // =========================================================================
191	    // Fixtures
192	    // =========================================================================
193	
194	    private function eventFor(User $admin, EventState $state): Event
195	    {
196	        return Event::factory()
197	            ->inState($state)
198	            ->for($admin->currentTeam)
199	            ->create(['created_by' => $admin->id]);
200	    }
201	
202	    private function registrationFor(Event $event): Registration
203	    {
204	        $email = 'registrant-'.$event->id.'@example.test';
205	
206	        $registration = new Registration;
207	        $registration->forceFill([
208	            'uuid' => sprintf('00000000-0000-4000-8000-%012x', $event->id),
209	            'team_id' => $event->team_id,
210	            'event_id' => $event->id,
211	            'email' => $email,
212	            'email_hash' => Hash::make($email),
213	            'full_name' => 'Registered Attendee',
214	        ]);
215	        $registration->save();
216	
217	        return $registration;
218	    }
219	}
