40	/**
41	 * Story 2-1 — thin controller. Validation lives in StoreEventRequest;
42	 * capability + persistence + audit live in EventService::createDraft.
43	 */
44	class EventController extends Controller
45	{
46	    public function __construct(
47	        private readonly EventService $eventService,
48	        private readonly EventActionAvailability $eventActionAvailability,
49	        private readonly EventSourceBreakdownReportService $sourceBreakdownReport,
50	        private readonly EventReportDashboardService $reportDashboard,
51	        private readonly AudienceBoostCampaignReportService $audienceBoostCampaignReport,
52	        private readonly EventOperationalLockService $operationalLocks,
53	        private readonly StreamingAssetOperationsService $streamingAssetOperations,
54	        private readonly ReplayRecordingDownloadService $recordingDownloads,
55	    ) {}
56	
57	    public function create(): View
58	    {
59	        if (! authUser()?->currentTeam) {
60	            abort(403, __('events.errors.no_active_workspace'));
61	        }
62	
63	        return view('events::events.create', [
64	            'breadcrumbs' => [
65	                ['label' => __('events.list.title'), 'route' => 'events.index'],
66	                ['label' => __('events.create.title'), 'route' => null],
67	            ],
68	            // Defaults: tomorrow at the current top-of-hour for start, +1 hour for end.
69	            'defaultStartsAt' => ($startsAt = now()->addDay()->startOfHour())->format('Y-m-d\TH:i'),
70	            'defaultEndsAt' => $startsAt->copy()->addHour()->format('Y-m-d\TH:i'),
71	            'defaultTimezone' => old('timezone', config('app.timezone', 'UTC')),
72	            'timezones' => $this->timezoneOptions(),
73	        ]);
74	    }
75	
76	    public function store(StoreEventRequest $request): JsonResponse|RedirectResponse
77	    {
78	        /** @var User $user */
79	        $user = authUser();
80	
81	        $team = $user->currentTeam;
82	        if (! $team) {
83	            abort(403, __('events.errors.no_active_workspace'));
84	        }
85	
86	        try {
87	            $event = $this->eventService->createDraft(
88	                team: $team,
89	                actor: $user,
90	                metadata: $request->eventMetadata(),
91	            );
92	        } catch (EventCreditExhaustedException $exception) {
93	            if (! $request->expectsJson()) {
94	                return redirect()
95	                    ->route('events.create')
96	                    ->withErrors(['create' => $exception->getMessage()])
97	                    ->withInput()
98	                    ->with('reference', $exception->errorCode());
99	            }
100	
101	            return response()->json([
102	                'error' => [
103	                    'code' => $exception->errorCode(),
104	                    'message' => $exception->getMessage(),
105	                ],
106	            ], $exception->httpStatus());
107	        }
108	
109	        if (! $request->expectsJson()) {
110	            return redirect()
111	                ->route('events.show', $event)
112	                ->with('status', __('events.create.success'));
113	        }
114	
115	        return response()->json([
