662	    /**
663	     * @return array<int, array{id: string, name: string, offset: int}>
664	     */
665	    private function timezoneOptions(): array
666	    {
667	        $now = new DateTimeImmutable('now');
668	        $options = array_map(static function (string $timezone) use ($now): array {
669	            $offset = (new DateTimeZone($timezone))->getOffset($now);
670	
671	            return [
672	                'id' => $timezone,
673	                'name' => sprintf('%s %s', self::formatOffset($offset), $timezone),
674	                'offset' => $offset,
675	            ];
676	        }, DateTimeZone::listIdentifiers(DateTimeZone::ALL));
677	
678	        usort($options, static function (array $left, array $right): int {
679	            if ($left['id'] === 'UTC') {
680	                return -1;
681	            }
682	
683	            if ($right['id'] === 'UTC') {
684	                return 1;
685	            }
686	
687	            return [abs($left['offset']), -$left['offset'], $left['id']]
688	                <=> [abs($right['offset']), -$right['offset'], $right['id']];
689	        });
690	
691	        return $options;
692	    }
693	
694	    private static function formatOffset(int $offset): string
695	    {
696	        $sign = $offset >= 0 ? '+' : '-';
697	        $absolute = abs($offset);
698	        $hours = intdiv($absolute, 3600);
699	        $minutes = intdiv($absolute % 3600, 60);
700	
701	        return sprintf('UTC%s%02d:%02d', $sign, $hours, $minutes);
702	    }
703	}
