1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Modules\Events\Services;
6	
7	use App\Models\Team;
8	use App\Models\User;
9	use App\Modules\Billing\Contracts\EventCreditServiceInterface;
10	use App\Modules\Events\Contracts\Repositories\EventRepositoryInterface;
11	use App\Modules\Events\Enums\EventState;
12	use App\Modules\Events\Enums\EventType;
13	use App\Modules\Events\Exceptions\EventStateLocked;
14	use App\Modules\Events\Models\Event;
15	use Illuminate\Support\Facades\DB;
16	use Illuminate\Support\Str;
17	use Platform\AuditLogging\Contracts\AuditLoggerInterface;
18	use App\Modules\Events\Support\EventAuditEvents;
19	
20	/**
21	 * Epic 2 refactor — metadata cluster extracted from EventService (createDraft + updateMetadata).
22	 *
23	 * Move-only: all bodies are byte-for-byte from EventService.
24	 * authorizeEventUpdate() is promoted to public so EventLandingService can
25	 * call it via injection (upsertLandingSetup / upsertRegistrationFormConfig
26	 * share the same authorization pattern).
27	 * Error-log tag updated: '[EventService]' → '[EventMetadataService]'.
28	 */
29	class EventMetadataService
30	{
31	    public function __construct(
32	        private readonly AuditLoggerInterface $auditLogger,
33	        private readonly EventRepositoryInterface $events,
34	        private readonly EventAuthorizationService $authz,
35	        private readonly EventCreditServiceInterface $credits,
36	    ) {}
37	
38	    /**
39	     * Create a DRAFT event scoped to the given team. Caller's capability
40	     * `events.create.team` is asserted before persistence.
41	     *
42	     * @param  array<string, mixed>  $metadata
43	     *                                          Required keys: title, description, starts_at, ends_at, timezone.
44	     */
45	    public function createDraft(Team $team, User $actor, array $metadata): Event
46	    {
47	        $this->authz->authorizeCreate($team, $actor);
48	
49	        return DB::transaction(function () use ($team, $actor, $metadata): Event {
50	            $event = new Event;
51	            $event->forceFill([
52	                'uuid' => (string) Str::uuid(),
53	                'team_id' => $team->getKey(),
54	                'state' => EventState::DRAFT->value,
55	                'title' => $metadata['title'],
56	                'description' => $metadata['description'],
57	                'type' => $metadata['type'] ?? EventType::WEBINAR->value,
58	                'starts_at' => $metadata['starts_at'],
59	                'ends_at' => $metadata['ends_at'],
60	                'timezone' => $metadata['timezone'],
61	                'registrant_capacity_limit' => $metadata['registrant_capacity_limit'] ?? null,
62	                // Story 3-11 / FR106 — persist organizer-set language; fallback to app default.
63	                'default_locale' => $metadata['default_locale'] ?? config('app.fallback_locale', 'en'),
64	                'created_by' => $actor->getKey(),
65	            ])->save();
66	
67	            // E-PKG S5 — bind and burn one event credit atomically with the
68	            // event row (owner rule: credits bind at creation and never
69	            // release). Throws EventCreditExhaustedException, which rolls back
70	            // this transaction so no event is created, when an active paid team
71	            // is out of credits. A Free team with no consumable source proceeds
72	            // UNBOUND (the returned result's source is FREE_SANDBOX); publish /
73	            // go-live stay entitlement-gated so an unbound event can't go public.
74	            $this->credits->consumeForEventCreation($team, $event);
75	
76	            $this->auditLogger->log(
77	                event: EventAuditEvents::EVENT_CREATED,
78	                description: "Event {$event->getKey()} created in team {$team->getKey()}",
79	                subject: $actor,
80	                target: $event,
81	                properties: [
82	                    'team_id' => $team->getKey(),
83	                    'event_uuid' => $event->uuid,
84	                    'type' => $event->type->value,
85	                    'timezone' => $event->timezone,
86	                ],
87	            );
88	
89	            return $event->refresh();
90	        });
91	    }
92	
93	    public function updateMetadata(Event $event, User $actor, array $changes): Event
94	    {
95	        $this->authorizeEventUpdate($event->team, $actor);
96	
97	        // R2 (2-2) — separate-tx denied audit, mirroring transition() / cancel().
98	        // Outer tx ONLY locks + reads + (on legal path) writes state + success audit.
99	        // Denied paths return ('denied', $reasonTag) WITHOUT touching the audit;
100	        // the post-tx block emits event.metadata_update_denied in its own tx with
101	        // try/catch + always-throw, so a logger failure cannot mask EventStateLocked.
102	        $result = DB::transaction(function () use ($event, $actor, $changes): array {
103	            $fresh = $this->events->lockEventForServiceWrite($event->getKey());
104	
105	            // R1 HIGH #3 (2-2) — cancellation wins forward (sketch §10 Q2).
106	            // A DRAFT event with cancelled_at set must reject metadata edits;
107	            // cancel is a flag, not a state, so isMetadataLocked() alone misses it.
108	            if ($fresh->cancelled_at !== null) {
109	                return [$fresh, 'denied', 'cancelled'];
110	            }
111	
112	            if ($fresh->state->isMetadataLocked()) {
113	                return [$fresh, 'denied', 'state_locked'];
114	            }
115	
116	            // Story 3-11 — default_locale is organizer-editable event metadata (FR106).
117	            $allowed = ['title', 'description', 'type', 'starts_at', 'ends_at', 'timezone', 'registrant_capacity_limit', 'default_locale'];
118	            $applied = array_intersect_key($changes, array_flip($allowed));
119	
120	            if (! empty($applied)) {
121	                $fresh->fill($applied)->save();
122	            }
123	
124	            // Success-path audit STAYS inside the outer tx — AC1 atomic
125	            // state+audit invariant. Logger throw rolls back state.
126	            $this->auditLogger->log(
127	                event: EventAuditEvents::EVENT_METADATA_UPDATED,
128	                description: "Event {$fresh->getKey()} metadata updated in team {$fresh->team_id}",
129	                subject: $actor,
130	                target: $fresh,
131	                properties: [
132	                    'team_id' => $fresh->team_id,
133	                    'event_uuid' => $fresh->uuid,
134	                    'changes' => array_keys($applied),
135	                ],
136	            );
137	
138	            return [$fresh->refresh(), 'changed', null];
139	        });
140	
141	        [$fresh, $outcome, $deniedReason] = $result;
142	
143	        if ($outcome === 'denied') {
144	            $description = $deniedReason === 'cancelled'
145	                ? "Event {$fresh->getKey()} metadata update denied (cancelled)"
146	                : "Event {$fresh->getKey()} metadata update denied (state {$fresh->state->value})";
147	
148	            $properties = [
149	                'team_id' => $fresh->team_id,
150	                'event_uuid' => $fresh->uuid,
151	                'reason' => $deniedReason,
152	                'attempted_changes' => array_keys($changes),
153	            ];
154	            if ($deniedReason === 'state_locked') {
155	                $properties['state'] = $fresh->state->value;
156	            }
157	
158	            // Best-effort denied-audit in a SEPARATE tx; logger failures are
159	            // reported but never mask EventStateLocked (mirrors transition()
160	            // / cancel() R2 patterns).
161	            try {
162	                DB::transaction(function () use ($actor, $fresh, $description, $properties): void {
163	                    $this->auditLogger->log(
164	                        event: EventAuditEvents::EVENT_METADATA_UPDATE_DENIED,
165	                        description: $description,
166	                        subject: $actor,
167	                        target: $fresh,
168	                        properties: $properties,
169	                    );
170	                });
171	            } catch (\Throwable $auditFailure) {
172	                if (function_exists('report')) {
173	                    report($auditFailure);
174	                } else {
175	                    error_log('[EventMetadataService] updateMetadata denied-audit storage failure: '.$auditFailure->getMessage());
176	                }
177	            }
178	
179	            throw EventStateLocked::for($fresh);
180	        }
181	
182	        return $fresh;
183	    }
184	
185	    /**
186	     * Assert actor may update (metadata) events in the given team.
187	     * Public so EventLandingService can call it via injection (upsertLandingSetup
188	     * and upsertRegistrationFormConfig share the same authorization pattern).
189	     *
190	     * Delegates to EventAuthorizationService::authorizeUpdate — single source of truth.
191	     */
192	    public function authorizeEventUpdate(Team $team, User $actor): void
193	    {
194	        $this->authz->authorizeUpdate($team, $actor);
195	    }
196	
197	}
