/**
 * T1 — duplicate an event into a fresh DRAFT owned by the acting team.
 *
 * Thin controller: EventService::duplicate owns both guards (view access on
 * the source + create capability on the acting team) so the endpoint refuses
 * independently of whether the UI rendered the action.
 */
public function duplicate(Request $request, Event $event): JsonResponse|RedirectResponse
{
    /** @var User $user */
    $user = authUser();

    try {
        $copy = $this->eventService->duplicate($event, $user);
    } catch (AuthorizationException) {
        if (! $request->expectsJson()) {
            abort(403, __('events.errors.unauthorized'));
        }

        return response()->json([
            'error' => ['code' => 'JKM-EVT-1010', 'message' => __('events.errors.unauthorized')],
        ], 403);
    } catch (EventCreditExhaustedException $exception) {
        if (! $request->expectsJson()) {
            return redirect()
                ->back()
                ->withErrors(['duplicate' => $exception->getMessage()])
                ->with('reference', $exception->errorCode());
        }

        return response()->json([
            'error' => [
                'code' => $exception->errorCode(),
                'message' => $exception->getMessage(),
            ],
        ], $exception->httpStatus());
    }

    if (! $request->expectsJson()) {
        return redirect()
            ->route('events.show', $copy)
            ->with('status', __('events.duplicate.success'));
    }

    return response()->json([
        'data' => [
            'uuid' => $copy->uuid,
            'state' => $copy->state->value,
            'title' => $copy->title,
        ],
    ], 201);
}

